1	package registry
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"strings"
7	)
8	
9	// ---- 整批转让 ----
10	
11	func (req TransferBatchRequest) validatePresent() error {
12		missing := []string{}
13		if strings.TrimSpace(req.Operator) == "" {
14			missing = append(missing, "operator")
15		}
16		if strings.TrimSpace(req.Reason) == "" {
17			missing = append(missing, "reason")
18		}
19		if strings.TrimSpace(req.RequestID) == "" {
20			missing = append(missing, "request_id")
21		}
22		if len(missing) > 0 {
23			return fmt.Errorf("%w: 整批转让请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
24		}
25		if len(req.Entries) == 0 {
26			return fmt.Errorf("%w: 整批转让清单不能为空", ErrInvalidArgument)
27		}
28		seen := make(map[string]bool, len(req.Entries))
29		for i, e := range req.Entries {
30			if strings.TrimSpace(e.ItemID) == "" {
31				return fmt.Errorf("%w: 清单第 %d 条缺少藏品编号", ErrInvalidArgument, i+1)
32			}
33			if seen[e.ItemID] {
34				return fmt.Errorf("%w: 清单内藏品编号 %s 重复", ErrInvalidArgument, e.ItemID)
35			}
36			seen[e.ItemID] = true
37			if strings.TrimSpace(e.ExpectedOwner) == "" {
38				return fmt.Errorf("%w: 清单第 %d 条（藏品 %s）缺少期望持有人",
39					ErrInvalidArgument, i+1, e.ItemID)
40			}
41			if strings.TrimSpace(e.ToID) == "" {
42				return fmt.Errorf("%w: 清单第 %d 条（藏品 %s）缺少接收账户",
43					ErrInvalidArgument, i+1, e.ItemID)
44			}
45			if e.ExpectedVer <= 0 {
46				return fmt.Errorf("%w: 清单第 %d 条（藏品 %s）期望版本必须为正，得到 %d",
47					ErrInvalidArgument, i+1, e.ItemID, e.ExpectedVer)
48			}
49			if e.Price < 0 {
50				return fmt.Errorf("%w: 清单第 %d 条（藏品 %s）成交价款 %d 不能为负",
51					ErrInvalidArgument, i+1, e.ItemID, e.Price)
52			}
53		}
54		return nil
55	}
56	
57	func transferBatchParamsSig(req TransferBatchRequest) string {
58		// 条目按提交顺序进入签名：改动任一条目内容或条目顺序都会得到不同
59		// 签名，按请求号冲突拒绝。Price 用 omitempty，与单件转让一致。
60		type entry struct {
61			ItemID        string `json:"item_id"`
62			ToID          string `json:"to_id"`
63			ExpectedOwner string `json:"expected_owner"`
64			ExpectedVer   int64  `json:"expected_version"`
65			Price         int64  `json:"price,omitempty"`
66		}
67		entries := make([]entry, 0, len(req.Entries))
68		for _, e := range req.Entries {
69			entries = append(entries, entry{
70				ItemID: e.ItemID, ToID: e.ToID, ExpectedOwner: e.ExpectedOwner,
71				ExpectedVer: e.ExpectedVer, Price: e.Price,
72			})
73		}
74		b, _ := json.Marshal(struct {
75			Kind    string  `json:"kind"`
76			Reason  string  `json:"reason"`
77			Entries []entry `json:"entries"`
78		}{"transfer_batch", req.Reason, entries})
79		return string(b)
80	}
81	
82	// TransferBatch 由持有人一次提交多件藏品，分别转给各自指定的接收账户，
83	// 整批共用操作者、原因与请求号。藏品可来自不同系列与发行批次，接收账户
84	// 可以重复；操作者必须是每件的当前持有人。
85	//
86	// 整批只能全部成功或全部拒绝：全部条目在同一临界区内按清单顺序依次转让，
87	// 各件版本分别加一，历史序号连续，整批记录之间不能插入其他发行或转让；
88	// 版税按各件所属系列首次发行时固定的规则快照分别计算，同一收款账户在
89	// 多件中出现也各自保留明细，不把价款合并后计算；零金额明细与归转让前
90	// 持有人的余款沿用单件转让规则。整批转让不使用任何代转授权，也不把已有
91	// 授权记为已使用；成功转出后，绑定旧版本的授权即使在藏品转回后也不能
92	// 恢复使用。系列封存不阻止转让。
93	//
94	// 空清单、重复藏品编号、必填内容缺失、非正期望版本或负价款按参数错误
95	// 拒绝。每件沿用单件转让的账户登记、停用、收发不同人与持有版本规则；
96	// 多件存在业务拒绝时，返回清单顺序最前的失败藏品及其错误；操作者未
97	// 登记或停用时只返回账户错误（ItemID 为空）。任何拒绝都不改变任何一件
98	// 的持有、版本、历史或应付。
99	//
100	// 请求号与已有操作共用同一操作者的范围：完全相同的内容及顺序重提，回放
101	// 首次成功或状态类拒绝并标明 Replayed（即使藏品后来再次易手或账户停用）；
102	// 改动原因、条目顺序或任一条目参数返回 ErrRequestConflict。参数错误与
103	// 引用不存在不占用请求号。并发重复只能完成一次；与其他整批、单件转让或
104	// 代转争用同一藏品版本时，最多一方成功。
105	func (r *Registry) TransferBatch(req TransferBatchRequest) (TransferBatchResult, error) {
106		if err := req.validatePresent(); err != nil {
107			return TransferBatchResult{}, err
108		}
109		r.mu.Lock()
110		defer r.mu.Unlock()
111		if err := r.checkOpen(); err != nil {
112			return TransferBatchResult{}, err
113		}
114	
115		key := requestKey(req.Operator, req.RequestID)
116		sig := transferBatchParamsSig(req)
117		if prev, ok := r.state.Requests[key]; ok {
118			return r.replayTransferBatch(prev, sig)
119		}
120	
121		itemID, bizErr := r.checkTransferBatch(req)
122		if bizErr != nil {
123			if !isValidationErr(bizErr) {
124				// 状态类业务拒绝（停用、收发同人、持有版本不符等）占用请求号
125				// 并落盘：相同参数重提永远返回这一次拒绝，即使状态后来变化。
126				r.state.Requests[key] = request{
127					Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer_batch",
128					Params: sig, Rejected: true, Reason: errCode(bizErr),
129					ItemID: itemID,
130				}
131				_ = r.commit()
132			}
133			// 藏品或账户不存在等校验错误不占用请求号，也不改变任何一件的持有、
134			// 版本、历史或应付。
135			return TransferBatchResult{ItemID: itemID, Err: bizErr}, bizErr
136		}
137	
138		// 在同一临界区内按清单顺序依次转让：各件版本分别加一、历史序号连续，
139		// 与其他整批、单件转让、代转或发行互斥，整批记录之间不会插入别的记录。
140		// 各件沿用与单件转让相同的持有、历史与版税落盘逻辑；同一收款账户在
141		// 多件中出现也各自落盘明细，价款不合并。
142		items := make([]TransferBatchItem, 0, len(req.Entries))
143		stored := make([]batchTransferItemResult, 0, len(req.Entries))
144		for _, e := range req.Entries {
145			out := r.applyTransfer(e.ItemID, e.ToID, req.Operator, req.Reason, req.RequestID, "", e.Price)
146			items = append(items, TransferBatchItem{
147				ItemID: e.ItemID, FromID: out.fromID, ToID: e.ToID, Version: out.toVer(),
148				TxSeq: out.seq, Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
149				Remainder: out.royalty.Remainder,
150			})
151			stored = append(stored, batchTransferItemResult{
152				ItemID: e.ItemID, FromID: out.fromID, ToID: e.ToID,
153				Version: out.toVer(), TxSeq: out.seq,
154			})
155		}
156		// 持有变化、历史、应付与请求结果在同一临界区内一次落盘：保存失败时
157		// 磁盘仍是整批前的完整状态，不会留下部分转让。
158		r.state.Requests[key] = request{
159			Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer_batch",
160			Params: sig, TransferBatch: stored,
161		}
162		if err := r.commit(); err != nil {
163			return TransferBatchResult{}, err
164		}
165		return TransferBatchResult{Items: items}, nil
166	}
167	
168	// checkTransferBatch 按整批转让的优先级执行与单件共用的直接转让资格
169	// 规则：操作者层面的错误（未登记或停用）最先返回且不关联具体藏品
170	// （ItemID 为空）；操作者可用后，按清单顺序逐件检查，只返回第一件失败
171	// 的藏品编号与错误，后面条目的错误不提前。任何一件不通过则整批拒绝。
172	func (r *Registry) checkTransferBatch(req TransferBatchRequest) (string, error) {
173		return r.checkBatchTransferEligibility(req.Operator, req.Entries)
174	}
175	
176	func (r *Registry) replayTransferBatch(prev request, sig string) (TransferBatchResult, error) {
177		if prev.Kind != "transfer_batch" || prev.Params != sig {
178			return TransferBatchResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
179				ErrRequestConflict, prev.Operator, prev.RequestID)
180		}
181		res := TransferBatchResult{ItemID: prev.ItemID, Replayed: true}
182		if prev.Rejected {
183			res.Err = codeErr(prev.Reason)
184			return res, res.Err
185		}
186		// 回放整批首次成功的转让结果：即使藏品后来再次易手、账户停用或进程
187		// 重开，仍返回原前后持有人、版本、序号与原价款/应付明细，不改写当前
188		// 状态，也不重复计入应付。
189		for _, bi := range prev.TransferBatch {
190			price, payables, remainder := r.royaltyOfTx(bi.TxSeq)
191			res.Items = append(res.Items, TransferBatchItem{
192				ItemID: bi.ItemID, FromID: bi.FromID, ToID: bi.ToID, Version: bi.Version,
193				TxSeq: bi.TxSeq, Price: price, Payables: payables, Remainder: remainder,
194			})
195		}
196		return res, nil
197	}
