598		}); !errors.Is(err, ErrConflict) {
599			t.Fatalf("proxy after return: %v", err)
600		}
601		a, _ = r.GetAuthorization("a1")
602		if a.Status != AuthActive {
603			t.Fatalf("authorization should never become used: %+v", a)
604		}
605	}
606	
607	// ---- 持久化 ----
608	
609	func TestTransferBatchPersistence(t *testing.T) {
610		dir := tempDir(t)
611		r := mustCreate(t, dir)
612		setupBatchTransferWorld(t, r)
613		req := tbtReq("rb1", tbtEntry("i1", "carol", 1, 10000), tbtEntry("i2", "dave", 1, 333))
614		first, err := r.TransferBatch(req)
615		if err != nil {
616			t.Fatal(err)
617		}
618		if err := r.Close(); err != nil {
619			t.Fatal(err)
620		}
621	
622		r2, err := Open(dir)
623		if err != nil {
624			t.Fatal(err)
625		}
626		t.Cleanup(func() { _ = r2.Close() })
627	
628		replay, err := r2.TransferBatch(req)
629		if err != nil {
630			t.Fatalf("replay after reopen: %v", err)
631		}
632		if !replay.Replayed || len(replay.Items) != 2 {
633			t.Fatalf("replay = %+v", replay)
634		}
635		for i := range first.Items {
636			if !reflect.DeepEqual(replay.Items[i], first.Items[i]) {
637				t.Errorf("item %d: %+v != %+v", i, replay.Items[i], first.Items[i])
638			}
639		}
640		h, err := r2.GetHolding("i1")
641		if err != nil || h.OwnerID != "carol" || h.Version != 2 {
642			t.Fatalf("holding after reopen: %+v %v", h, err)
643		}
644		hist, err := r2.History("i2")
645		if err != nil || len(hist) != 2 || hist[1].RequestID != "rb1" {
646			t.Fatalf("history after reopen: %+v %v", hist, err)
647		}
648		// 应付明细与余款完整保留。
649		for _, w := range first.Items {
650			tr, err := r2.TransferRoyalty(w.TxSeq)
651			if err != nil {
652				t.Fatalf("TransferRoyalty %d: %v", w.TxSeq, err)
653			}
654			if tr.Price != w.Price || tr.Remainder != w.Remainder || len(tr.Payables) != len(w.Payables) {
655				t.Fatalf("royalty %d after reopen = %+v, want %+v", w.TxSeq, tr, w)
656			}
657		}
658	}
659	
660	// ---- 并发 ----
661	
662	// 并发重复提交同一请求只完成一次，其余全部回放首次结果。
663	func TestTransferBatchConcurrentSameRequest(t *testing.T) {
664		r := mustCreate(t, tempDir(t))
665		setupBatchTransferWorld(t, r)
666		req := tbtReq("rb1", tbtEntry("i1", "carol", 1, 100), tbtEntry("i2", "dave", 1, 200))
667	
668		const n = 8
669		var wg sync.WaitGroup
670		errs := make([]error, n)
671		results := make([]TransferBatchResult, n)
672		for i := 0; i < n; i++ {
673			wg.Add(1)
674			go func(i int) {
675				defer wg.Done()
676				results[i], errs[i] = r.TransferBatch(req)
677			}(i)
678		}
679		wg.Wait()
680		replayed := 0
681		for i := range errs {
682			if errs[i] != nil {
683				t.Fatalf("goroutine %d: %v", i, errs[i])
684			}
685			if len(results[i].Items) != 2 {
686				t.Fatalf("goroutine %d: %+v", i, results[i])
687			}
688			if results[i].Replayed {
689				replayed++
690			}
691		}
692		if replayed != n-1 {
693			t.Fatalf("replayed = %d, want %d", replayed, n-1)
694		}
695		// 每件只转让一次：版本 2、历史两条。
696		for _, id := range []string{"i1", "i2"} {
697			h, err := r.GetHolding(id)
698			if err != nil {
699				t.Fatal(err)
700			}
701			if h.Version != 2 {
702				t.Fatalf("%s version = %d, want 2", id, h.Version)
703			}
704			hist, err := r.History(id)
705			if err != nil {
706				t.Fatal(err)
707			}
708			if len(hist) != 2 {
709				t.Fatalf("%s history len = %d", id, len(hist))
710			}
711		}
712		// 每件应付只记一次：i1（s1，carol 10%）与 i2（s2，carol 100%）各一条。
713		carolPay, _ := r.PayablesOf("carol")
714		if len(carolPay) != 2 {
715			t.Fatalf("carol payables = %+v, want exactly 2 lines", carolPay)
716		}
717		amounts := map[int64]int64{}
718		for _, p := range carolPay {
719			amounts[p.TxSeq] = p.Amount
720		}
721		if amounts[6] != 10 || amounts[7] != 200 {
722			t.Fatalf("carol payable amounts = %+v, want {6:10 7:200}", amounts)
723		}
724	}
725	
726	// 整批与单件转让、其他整批、代转争用同一藏品版本：最多一方成功；失败
727	// 整批中的其他藏品保持原状。
728	func TestTransferBatchConcurrentContention(t *testing.T) {
729		r := mustCreate(t, tempDir(t))
730		setupBatchTransferWorld(t, r)
731		// 额外为 i2 准备一份代转授权（受托人 carol，接收人 alice）。
732		expires := r.now().Add(3600e9)
733		if _, err := r.CreateAuthorization(CreateAuthorizationRequest{
734			Operator: "bob", Reason: "委托", RequestID: "ra1", AuthID: "a1",
735			ItemID: "i2", TrusteeID: "carol", ToID: "alice",
736			ExpectedOwner: "bob", ExpectedVer: 1, ExpiresAt: expires,
737		}); err != nil {
738			t.Fatal(err)
739		}
740	
741		const n = 4
742		var wg sync.WaitGroup
743		errs := make([]error, n)
744		run := func(i int, fn func() error) {
745			wg.Add(1)
746			go func() {
747				defer wg.Done()
748				errs[i] = fn()
749			}()
750		}
751		// 整批 A：争 i1，另带 i3。
752		run(0, func() error {
753			_, e := r.TransferBatch(tbtReq("rb-a", tbtEntry("i1", "carol", 1, 1), tbtEntry("i3", "dave", 1, 1)))
754			return e
755		})
756		// 单件转让：争 i1。
757		run(1, func() error {
758			_, e := r.Transfer(TransferRequest{
759				Operator: "bob", Reason: "卖出", RequestID: "rt-s", ItemID: "i1",
760				ExpectedOwner: "bob", ExpectedVer: 1, ToID: "dave",
761			})
762			return e
763		})
764		// 另一整批：争 i1 与 i2。
765		run(2, func() error {
766			_, e := r.TransferBatch(tbtReq("rb-c", tbtEntry("i1", "alice", 1, 1), tbtEntry("i2", "dave", 1, 1)))
767			return e
768		})
769		// 代转：争 i2。
770		run(3, func() error {
771			_, e := r.ProxyTransfer(ProxyTransferRequest{
772				Operator: "carol", Reason: "代转", RequestID: "rp-1", AuthID: "a1",
773			})
774			return e
775		})
776		wg.Wait()
777	
778		ok := 0
779		for i, err := range errs {
780			if err == nil {
781				ok++
782				continue
783			}
784			if !errors.Is(err, ErrConflict) {
785				t.Fatalf("goroutine %d unexpected error: %v", i, err)
786			}
787		}
788		// i1 的三方争用（整批 A、单件、整批 C）恰好一方得手；i2 的两方争用
789		// （整批 C、代转）恰好一方得手。整批 C 同时赢得两件时只有一个操作
790		// 成功（ok=1），否则各由一方赢得（ok=2）。
791		if ok != 1 && ok != 2 {
792			t.Fatalf("success = %d, want 1 or 2 (errors %+v)", ok, errs)
793		}
794		// 整批 C 成功时 i1 与 i2 都在其名下；否则 i2 必由代转转入 alice。
795		batchCWon := errs[2] == nil
796		h1, _ := r.GetHolding("i1")
797		h2, _ := r.GetHolding("i2")
798		if batchCWon {
799			if ok != 1 || h1.OwnerID != "alice" || h2.OwnerID != "dave" {
800				t.Fatalf("batch C won: ok=%d h1=%+v h2=%+v", ok, h1, h2)
801			}
802		} else {
803			if ok != 2 || h2.OwnerID != "alice" {
804				t.Fatalf("batch C lost: ok=%d h2=%+v", ok, h2)
805			}
806		}
807	
808		for _, id := range []string{"i1", "i2"} {
809			h, err := r.GetHolding(id)
810			if err != nil {
811				t.Fatal(err)
812			}
813			if h.Version != 2 {
814				t.Fatalf("%s transferred more than once: %+v", id, h)
815			}
816		}
817		// 失败整批中的其他藏品保持原状：整批 A 没得手 i1 时 i3 仍在 bob 手中。
818		if h1.OwnerID != "carol" {
819			h3, err := r.GetHolding("i3")
820			if err != nil {
821				t.Fatal(err)
822			}
823			if h3.OwnerID != "bob" || h3.Version != 1 {
824				t.Fatalf("losing batch must leave other items untouched, i3 = %+v", h3)
825			}
826		}
827		// 整批内序号连续且全局无空洞：成功条目数为 2（整批 C 或 单件+代转）
828		// 或 3（整批 A + 代转），序号恰为从 6 开始的连续区间。
829		seqs := map[int64]bool{}
830		for _, id := range []string{"i1", "i2", "i3", "i4"} {
831			hist, err := r.History(id)
832			if err != nil {
833				t.Fatal(err)
834			}
835			for _, e := range hist {
836				if e.Kind == "transfer" {
837					seqs[e.Seq] = true
838				}
839			}
840		}
841		if len(seqs) != 2 && len(seqs) != 3 {
842			t.Fatalf("transfer seqs = %+v, want 2 or 3", seqs)
843		}
844		for s := int64(6); s < 6+int64(len(seqs)); s++ {
845			if !seqs[s] {
846				t.Fatalf("seq %d missing, seqs = %+v", s, seqs)
847			}
848		}
849	}
850	
851	// 停用与转让在同一把锁上严格串行，只有两种先后：停用先完成则整批拒绝，
852	// 转让先完成则保留整批结果（回放不再受停用影响）。两种次序都确定性覆盖。
853	func TestTransferBatchRaceWithDeactivation(t *testing.T) {
854		t.Run("转让先完成", func(t *testing.T) {
855			r := mustCreate(t, tempDir(t))
856			setupBatchTransferWorld(t, r)
857			req := tbtReq("rb1", tbtEntry("i1", "carol", 1, 1))
858			if _, err := r.TransferBatch(req); err != nil {
859				t.Fatalf("batch: %v", err)
860			}
861			// 转让落盘后接收账户才停用：结果保留。
862			if err := r.DeactivateAccount("carol"); err != nil {
863				t.Fatal(err)
864			}
865			h, _ := r.GetHolding("i1")
866			if h.OwnerID != "carol" || h.Version != 2 {
867				t.Fatalf("holding = %+v", h)
868			}
869			replay, err := r.TransferBatch(req)
870			if err != nil || !replay.Replayed || replay.Items[0].ToID != "carol" {
871				t.Fatalf("replay after deactivation: %+v %v", replay, err)
872			}
873		})
874	
875		t.Run("停用先完成", func(t *testing.T) {
876			r := mustCreate(t, tempDir(t))
877			setupBatchTransferWorld(t, r)
878			// 操作者停用先完成：整批只返回账户错误且原子拒绝。
879			if err := r.DeactivateAccount("bob"); err != nil {
880				t.Fatal(err)
881			}
882			res, err := r.TransferBatch(tbtReq("rb1", tbtEntry("i1", "carol", 1, 1)))
883			if !errors.Is(err, ErrAccountInactive) {
884				t.Fatalf("err = %v, want ErrAccountInactive", err)
885			}
886			if res.ItemID != "" {
887				t.Fatalf("ItemID = %q, want empty", res.ItemID)
888			}
889			h, _ := r.GetHolding("i1")
890			if h.OwnerID != "bob" || h.Version != 1 {
891				t.Fatalf("holding changed: %+v", h)
892			}
893		})
894	
895		t.Run("接收账户停用先完成", func(t *testing.T) {
896			r := mustCreate(t, tempDir(t))
897			setupBatchTransferWorld(t, r)
898			if err := r.DeactivateAccount("carol"); err != nil {
899				t.Fatal(err)
900			}
901			res, err := r.TransferBatch(tbtReq("rb1",
902				tbtEntry("i1", "dave", 1, 1), tbtEntry("i3", "carol", 1, 1)))
903			if !errors.Is(err, ErrAccountInactive) || res.ItemID != "i3" {
904				t.Fatalf("res = %+v, err = %v", res, err)
905			}
906			// 整批原子拒绝：第一件 i1 也未转出。
907			h, _ := r.GetHolding("i1")
908			if h.OwnerID != "bob" || h.Version != 1 {
909				t.Fatalf("i1 changed: %+v", h)
910			}
911		})
912	}
