			t.Fatalf("err = %v, want ErrConflict", err)
		}
		if res.ItemID != "i2" {
			t.Fatalf("ItemID = %q, want i2", res.ItemID)
		}

		// 任何拒绝都不改变任何一件：i1 也保持原持有与版本，无新历史、无应付，
		// 历史序号未被消耗。
		for _, id := range []string{"i1", "i2", "i3"} {
