// ---- 代转授权：整批不消耗授权，旧版本授权不恢复 ----

func TestTransferBatchAuthorizationInteraction(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	setupBatchTransferWorld(t, r)

	expires := r.now().Add(3600e9)
	if _, err := r.CreateAuthorization(CreateAuthorizationRequest{
		Operator: "bob", Reason: "委托", RequestID: "ra1", AuthID: "a1",
		ItemID: "i1", TrusteeID: "carol", ToID: "alice",
		ExpectedOwner: "bob", ExpectedVer: 1, ExpiresAt: expires,
	}); err != nil {
		t.Fatal(err)
	}

	// 整批转让 i1：授权不被记为已使用。
	if _, err := r.TransferBatch(tbtReq("rt1", tbtEntry("i1", "dave", 1, 100))); err != nil {
		t.Fatal(err)
	}
	a, err := r.GetAuthorization("a1")
	if err != nil {
		t.Fatal(err)
	}
	if a.Status != AuthActive || a.UsedTxSeq != 0 {
		t.Fatalf("authorization should remain active, got %+v", a)
	}
	events, err := r.AuthorizationHistory("i1")
	if err != nil {
		t.Fatal(err)
	}
	if len(events) != 1 || events[0].Kind != "create" {
		t.Fatalf("auth events = %+v", events)
	}

	// 授权绑定旧版本：代转立即冲突。
	if _, err := r.ProxyTransfer(ProxyTransferRequest{
		Operator: "carol", Reason: "代转", RequestID: "rp1", AuthID: "a1",
	}); !errors.Is(err, ErrConflict) {
		t.Fatalf("proxy after batch: %v", err)
	}

	// 藏品转回 bob 后旧授权仍不可用。
	if _, err := r.Transfer(TransferRequest{
		Operator: "dave", Reason: "退回", RequestID: "rx2", ItemID: "i1",
		ExpectedOwner: "dave", ExpectedVer: 2, ToID: "bob",
	}); err != nil {
		t.Fatal(err)
	}
	if _, err := r.ProxyTransfer(ProxyTransferRequest{
		Operator: "carol", Reason: "代转", RequestID: "rp2", AuthID: "a1",
	}); !errors.Is(err, ErrConflict) {
		t.Fatalf("proxy after return: %v", err)
	}
	a, _ = r.GetAuthorization("a1")
	if a.Status != AuthActive {
		t.Fatalf("authorization should never become used: %+v", a)
	}
}

// ---- 持久化 ----

func TestTransferBatchPersistence(t *testing.T) {
	dir := tempDir(t)
	r := mustCreate(t, dir)
	setupBatchTransferWorld(t, r)
	req := tbtReq("rb1", tbtEntry("i1", "carol", 1, 10000), tbtEntry("i2", "dave", 1, 333))
	first, err := r.TransferBatch(req)
	if err != nil {
		t.Fatal(err)
	}
	if err := r.Close(); err != nil {
		t.Fatal(err)
	}

	r2, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = r2.Close() })

	replay, err := r2.TransferBatch(req)
	if err != nil {
		t.Fatalf("replay after reopen: %v", err)
	}
	if !replay.Replayed || len(replay.Items) != 2 {
		t.Fatalf("replay = %+v", replay)
	}
	for i := range first.Items {
		if !reflect.DeepEqual(replay.Items[i], first.Items[i]) {
			t.Errorf("item %d: %+v != %+v", i, replay.Items[i], first.Items[i])
		}
	}
	h, err := r2.GetHolding("i1")
	if err != nil || h.OwnerID != "carol" || h.Version != 2 {
		t.Fatalf("holding after reopen: %+v %v", h, err)
	}
	hist, err := r2.History("i2")
	if err != nil || len(hist) != 2 || hist[1].RequestID != "rb1" {
		t.Fatalf("history after reopen: %+v %v", hist, err)
	}
	// 应付明细与余款完整保留。
	for _, w := range first.Items {
		tr, err := r2.TransferRoyalty(w.TxSeq)
		if err != nil {
			t.Fatalf("TransferRoyalty %d: %v", w.TxSeq, err)
		}
		if tr.Price != w.Price || tr.Remainder != w.Remainder || len(tr.Payables) != len(w.Payables) {
			t.Fatalf("royalty %d after reopen = %+v, want %+v", w.TxSeq, tr, w)
		}
	}
}

// ---- 并发 ----

// 并发重复提交同一请求只完成一次，其余全部回放首次结果。
func TestTransferBatchConcurrentSameRequest(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	setupBatchTransferWorld(t, r)
	req := tbtReq("rb1", tbtEntry("i1", "carol", 1, 100), tbtEntry("i2", "dave", 1, 200))

	const n = 8
	var wg sync.WaitGroup
	errs := make([]error, n)
	results := make([]TransferBatchResult, n)
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			results[i], errs[i] = r.TransferBatch(req)
		}(i)
	}
	wg.Wait()
	replayed := 0
	for i := range errs {
		if errs[i] != nil {
			t.Fatalf("goroutine %d: %v", i, errs[i])
		}
		if len(results[i].Items) != 2 {
			t.Fatalf("goroutine %d: %+v", i, results[i])
		}
		if results[i].Replayed {
			replayed++
		}
	}
	if replayed != n-1 {
		t.Fatalf("replayed = %d, want %d", replayed, n-1)
	}
	// 每件只转让一次：版本 2、历史两条。
	for _, id := range []string{"i1", "i2"} {
		h, err := r.GetHolding(id)
		if err != nil {
			t.Fatal(err)
		}
		if h.Version != 2 {
			t.Fatalf("%s version = %d, want 2", id, h.Version)
		}
		hist, err := r.History(id)
		if err != nil {
			t.Fatal(err)
		}
		if len(hist) != 2 {
			t.Fatalf("%s history len = %d", id, len(hist))
		}
	}
	// 每件应付只记一次：i1（s1，carol 10%）与 i2（s2，carol 100%）各一条。
	carolPay, _ := r.PayablesOf("carol")
	if len(carolPay) != 2 {
		t.Fatalf("carol payables = %+v, want exactly 2 lines", carolPay)
	}
	amounts := map[int64]int64{}
	for _, p := range carolPay {
		amounts[p.TxSeq] = p.Amount
	}
	if amounts[6] != 10 || amounts[7] != 200 {
		t.Fatalf("carol payable amounts = %+v, want {6:10 7:200}", amounts)
	}
}

// 整批与单件转让、其他整批、代转争用同一藏品版本：最多一方成功；失败
// 整批中的其他藏品保持原状。
func TestTransferBatchConcurrentContention(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	setupBatchTransferWorld(t, r)
	// 额外为 i2 准备一份代转授权（受托人 carol，接收人 alice）。
	expires := r.now().Add(3600e9)
	if _, err := r.CreateAuthorization(CreateAuthorizationRequest{
		Operator: "bob", Reason: "委托", RequestID: "ra1", AuthID: "a1",
		ItemID: "i2", TrusteeID: "carol", ToID: "alice",
		ExpectedOwner: "bob", ExpectedVer: 1, ExpiresAt: expires,
	}); err != nil {
		t.Fatal(err)
	}

	const n = 4
	var wg sync.WaitGroup
	errs := make([]error, n)
	run := func(i int, fn func() error) {
		wg.Add(1)
		go func() {
			defer wg.Done()
			errs[i] = fn()
		}()
	}
	// 整批 A：争 i1，另带 i3。
	run(0, func() error {
		_, e := r.TransferBatch(tbtReq("rb-a", tbtEntry("i1", "carol", 1, 1), tbtEntry("i3", "dave", 1, 1)))
		return e
	})
	// 单件转让：争 i1。
	run(1, func() error {
		_, e := r.Transfer(TransferRequest{
			Operator: "bob", Reason: "卖出", RequestID: "rt-s", ItemID: "i1",
			ExpectedOwner: "bob", ExpectedVer: 1, ToID: "dave",
		})
		return e
	})
	// 另一整批：争 i1 与 i2。
	run(2, func() error {
		_, e := r.TransferBatch(tbtReq("rb-c", tbtEntry("i1", "alice", 1, 1), tbtEntry("i2", "dave", 1, 1)))
		return e
	})
	// 代转：争 i2。
	run(3, func() error {
		_, e := r.ProxyTransfer(ProxyTransferRequest{
			Operator: "carol", Reason: "代转", RequestID: "rp-1", AuthID: "a1",
		})
		return e
	})
	wg.Wait()

	ok := 0
	for i, err := range errs {
		if err == nil {
			ok++
			continue
		}
		if !errors.Is(err, ErrConflict) {
			t.Fatalf("goroutine %d unexpected error: %v", i, err)
		}
	}
	// i1 的三方争用（整批 A、单件、整批 C）恰好一方得手；i2 的两方争用
	// （整批 C、代转）恰好一方得手。整批 C 同时赢得两件时只有一个操作
	// 成功（ok=1），否则各由一方赢得（ok=2）。
	if ok != 1 && ok != 2 {
		t.Fatalf("success = %d, want 1 or 2 (errors %+v)", ok, errs)
	}
	// 整批 C 成功时 i1 与 i2 都在其名下；否则 i2 必由代转转入 alice。
	batchCWon := errs[2] == nil
	h1, _ := r.GetHolding("i1")
	h2, _ := r.GetHolding("i2")
	if batchCWon {
		if ok != 1 || h1.OwnerID != "alice" || h2.OwnerID != "dave" {
			t.Fatalf("batch C won: ok=%d h1=%+v h2=%+v", ok, h1, h2)
		}
	} else {
		if ok != 2 || h2.OwnerID != "alice" {
			t.Fatalf("batch C lost: ok=%d h2=%+v", ok, h2)
		}
	}

	for _, id := range []string{"i1", "i2"} {
		h, err := r.GetHolding(id)
		if err != nil {
			t.Fatal(err)
		}
		if h.Version != 2 {
			t.Fatalf("%s transferred more than once: %+v", id, h)
		}
	}
	// 失败整批中的其他藏品保持原状：整批 A 没得手 i1 时 i3 仍在 bob 手中。
	if h1.OwnerID != "carol" {
		h3, err := r.GetHolding("i3")
		if err != nil {
			t.Fatal(err)
		}
		if h3.OwnerID != "bob" || h3.Version != 1 {
			t.Fatalf("losing batch must leave other items untouched, i3 = %+v", h3)
		}
	}
	// 整批内序号连续且全局无空洞：成功条目数为 2（整批 C 或 单件+代转）
	// 或 3（整批 A + 代转），序号恰为从 6 开始的连续区间。
	seqs := map[int64]bool{}
	for _, id := range []string{"i1", "i2", "i3", "i4"} {
		hist, err := r.History(id)
		if err != nil {
			t.Fatal(err)
		}
		for _, e := range hist {
			if e.Kind == "transfer" {
				seqs[e.Seq] = true
			}
		}
	}
	if len(seqs) != 2 && len(seqs) != 3 {
		t.Fatalf("transfer seqs = %+v, want 2 or 3", seqs)
	}
	for s := int64(6); s < 6+int64(len(seqs)); s++ {
		if !seqs[s] {
			t.Fatalf("seq %d missing, seqs = %+v", s, seqs)
		}
	}
}

// 停用与转让在同一把锁上严格串行，只有两种先后：停用先完成则整批拒绝，
// 转让先完成则保留整批结果（回放不再受停用影响）。两种次序都确定性覆盖。
func TestTransferBatchRaceWithDeactivation(t *testing.T) {
	t.Run("转让先完成", func(t *testing.T) {
		r := mustCreate(t, tempDir(t))
		setupBatchTransferWorld(t, r)
		req := tbtReq("rb1", tbtEntry("i1", "carol", 1, 1))
		if _, err := r.TransferBatch(req); err != nil {
			t.Fatalf("batch: %v", err)
		}
		// 转让落盘后接收账户才停用：结果保留。
		if err := r.DeactivateAccount("carol"); err != nil {
			t.Fatal(err)
		}
		h, _ := r.GetHolding("i1")
		if h.OwnerID != "carol" || h.Version != 2 {
			t.Fatalf("holding = %+v", h)
		}
		replay, err := r.TransferBatch(req)
		if err != nil || !replay.Replayed || replay.Items[0].ToID != "carol" {
			t.Fatalf("replay after deactivation: %+v %v", replay, err)
		}
	})

	t.Run("停用先完成", func(t *testing.T) {
		r := mustCreate(t, tempDir(t))
		setupBatchTransferWorld(t, r)
		// 操作者停用先完成：整批只返回账户错误且原子拒绝。
		if err := r.DeactivateAccount("bob"); err != nil {
			t.Fatal(err)
		}
		res, err := r.TransferBatch(tbtReq("rb1", tbtEntry("i1", "carol", 1, 1)))
		if !errors.Is(err, ErrAccountInactive) {
			t.Fatalf("err = %v, want ErrAccountInactive", err)
		}
		if res.ItemID != "" {
			t.Fatalf("ItemID = %q, want empty", res.ItemID)
		}
		h, _ := r.GetHolding("i1")
		if h.OwnerID != "bob" || h.Version != 1 {
			t.Fatalf("holding changed: %+v", h)
		}
	})

	t.Run("接收账户停用先完成", func(t *testing.T) {
		r := mustCreate(t, tempDir(t))
		setupBatchTransferWorld(t, r)
		if err := r.DeactivateAccount("carol"); err != nil {
			t.Fatal(err)
		}
		res, err := r.TransferBatch(tbtReq("rb1",
			tbtEntry("i1", "dave", 1, 1), tbtEntry("i3", "carol", 1, 1)))
		if !errors.Is(err, ErrAccountInactive) || res.ItemID != "i3" {
			t.Fatalf("res = %+v, err = %v", res, err)
		}
		// 整批原子拒绝：第一件 i1 也未转出。
		h, _ := r.GetHolding("i1")
		if h.OwnerID != "bob" || h.Version != 1 {
			t.Fatalf("i1 changed: %+v", h)
		}
	})
}

package registry

import "time"

// Account 是账户登记信息。停用后仍可查询其原有藏品与历史。
type Account struct {
	ID       string // 唯一编号
	Metadata string // 文字元数据，可为空
	Active   bool   // 是否可用；停用后不能发行、发起或接收新的转让
}

// Series 是系列信息。仅创建账户可以发行藏品或封存系列。
type Series struct {
	ID        string // 系列编号
	CreatorID string // 创建账户编号
	Metadata  string // 文字元数据
	Sealed    bool   // 是否已封存；封存不可撤销
}

// Item 是单件藏品的静态登记信息。
type Item struct {
	ID         string // 唯一藏品编号，同一编号不能产生第二件藏品
	SeriesID   string // 所属系列
	BatchNo    string // 批次号
	Metadata   string // 文字元数据
	IssuedTxID int64  // 发行记录在历史中的序号
}

// Holding 是一件藏品的当前持有状态。
type Holding struct {
	ItemID  string // 藏品编号
	OwnerID string // 当前持有人
	Version int64  // 当前持有版本：发行后为 1，每次成功转让加 1
}

// HistoryEntry 是一条发行或成功转让记录，按发生先后排列。
type HistoryEntry struct {
	Seq       int64  // 严格递增的记录序号，也即发生顺序
	Kind      string // "issue" 或 "transfer"（代转仍为 transfer）
	ItemID    string // 藏品编号
	Operator  string // 操作者账户编号
	Reason    string // 操作原因
	RequestID string // 请求号
	// FromID 是转让前持有人；发行前为空。
	FromID string
	// ToID 是转让后持有人（发行时为初始持有人）。
	ToID string
	// FromVersion 是转让前持有版本；发行前为 0（语义上为空）。
	FromVersion int64
	// ToVersion 是转让后持有版本（发行后为 1）。
	ToVersion int64
	// AuthID 是代转所使用的授权编号；直接转让与发行时为空。
	AuthID string
}

// IssueRequest 是发行请求的业务参数（幂等判定以此为准）。
type IssueRequest struct {
	Operator  string // 操作者，必须是系列创建账户且可用
	Reason    string // 原因
	RequestID string // 请求号，同一操作者在发行与转让之间共用
	ItemID    string // 唯一藏品编号
	SeriesID  string // 所属系列
	BatchNo   string // 批次号
	Metadata  string // 藏品文字元数据
	HolderID  string // 初始持有人，必须是已登记且可用的账户
}

// IssueBatchEntry 是整批发行中一件藏品的提交内容。
type IssueBatchEntry struct {
	ItemID   string // 唯一藏品编号，清单内不能重复
	Metadata string // 藏品文字元数据，可为空
	HolderID string // 初始持有人，必须是已登记且可用的账户
}

// IssueBatchRequest 是整批发行请求的业务参数（幂等判定以此为准，含条目
// 顺序）。整批共用操作者、原因、请求号、系列与批次号。
type IssueBatchRequest struct {
	Operator  string            // 操作者，必须是系列创建账户且可用
	Reason    string            // 原因
	RequestID string            // 请求号，与单件发行、转让等共用同一操作者的请求号范围
	SeriesID  string            // 所属系列，整批同一系列
	BatchNo   string            // 批次号，整批同一批次；不同请求可沿用同一批次号
	Entries   []IssueBatchEntry // 发行清单，按提交顺序依次发行；不能为空
}

// IssueBatchItem 是整批发行中一件藏品的发行结果。
type IssueBatchItem struct {
	ItemID  string // 藏品编号
	OwnerID string // 初始持有人
	Version int64  // 持有版本，恒为 1
	TxSeq   int64  // 发行历史序号；整批内连续递增
}

// IssueBatchResult 是整批发行请求的处理结果。
type IssueBatchResult struct {
	Items []IssueBatchItem // 各件的发行结果，按提交顺序排列；拒绝时为空
	// ItemID 是业务拒绝所涉及的藏品编号（如编号已占用、初始持有人不可用的
	// 那一件）；拒绝与具体某件无关时为空。
	ItemID   string
	Replayed bool  // 是否为重复提交回放的首次结果
	Err      error // 首次或本次的业务拒绝；成功时为 nil
}

// TransferRequest 是转让请求的业务参数。
type TransferRequest struct {
	Operator      string // 操作者，必须是当前持有人且可用
	Reason        string // 原因
	RequestID     string // 请求号
	ItemID        string // 藏品编号
	ExpectedOwner string // 期望当前持有人（通常即发起人）
	ExpectedVer   int64  // 期望当前持有版本
	ToID          string // 接收人，必须已登记、可用且不同于当前持有人
	// Price 是成交价款，以分计，非负；未填按 0。负数按参数错误拒绝。
	Price int64
}

// IssueResult 是发行请求的处理结果。
type IssueResult struct {
	ItemID   string // 藏品编号
	OwnerID  string // 初始持有人
	Version  int64  // 持有版本，恒为 1
	TxSeq    int64  // 发行历史序号
	Replayed bool   // 是否为重复提交回放的首次结果
	Err      error  // 首次或本次的业务拒绝；成功时为 nil
}

// TransferResult 是转让请求的处理结果。
type TransferResult struct {
	ItemID   string // 藏品编号
	FromID   string // 转让前持有人
	ToID     string // 转让后持有人
	Version  int64  // 转让后版本
	TxSeq    int64  // 转让历史序号
	Replayed bool   // 是否为重复提交回放的首次结果
	Err      error  // 业务拒绝；成功时为 nil
	// Price 是本笔成交价款（分）；Payables 是各版税收款账户的应付明细
	// （含零金额）；Remainder 是扣除应付后归转让前持有人的剩余收入。
	Price     int64
	Payables  []RoyaltyPayable
	Remainder int64
}

// TransferBatchEntry 是整批转让中一件藏品的提交内容。
type TransferBatchEntry struct {
	ItemID        string // 藏品编号，清单内不能重复
	ToID          string // 接收账户，必须已登记且可用；不同条目可重复
	ExpectedOwner string // 期望当前持有人；操作者必须是每件的当前持有人
	ExpectedVer   int64  // 期望当前持有版本，必须为正
	// Price 是本件成交价款，以分计，非负；未填按 0。负数按参数错误拒绝。
	Price int64
}

// TransferBatchRequest 是整批转让请求的业务参数（幂等判定以此为准，含
// 条目顺序）。整批共用操作者、原因与请求号；藏品可来自不同系列与发行
// 批次。
type TransferBatchRequest struct {
	Operator  string               // 操作者，必须是每件的当前持有人且可用
	Reason    string               // 原因
	RequestID string               // 请求号，与发行、单件转让、代转等共用同一操作者的请求号范围
	Entries   []TransferBatchEntry // 转让清单，按提交顺序处理与返回；不能为空
}

// TransferBatchItem 是整批转让中一件藏品的转让结果。
type TransferBatchItem struct {
	ItemID   string           // 藏品编号
	FromID   string           // 转让前持有人
	ToID     string           // 转让后持有人
	Version  int64            // 转让后版本（各件分别加一）
	TxSeq    int64            // 转让历史序号；整批内连续递增
	Price    int64            // 本件成交价款（分）
	Payables []RoyaltyPayable // 本件各版税收款账户的应付明细（含零金额）
	// Remainder 是本件扣除应付后归转让前持有人的剩余收入。
	Remainder int64
}

// TransferBatchResult 是整批转让请求的处理结果。
type TransferBatchResult struct {
	Items []TransferBatchItem // 各件的转让结果，按提交顺序排列；拒绝时为空
	// ItemID 是业务拒绝所涉及的藏品编号（清单顺序最前的失败藏品）；
	// 操作者层面的拒绝（未登记或停用）时为空。
	ItemID   string
	Replayed bool  // 是否为重复提交回放的首次结果
	Err      error // 首次或本次的业务拒绝；成功时为 nil
}

// 授权生命周期状态。
const (
	// AuthActive 表示授权已创建，尚未撤销、过期或使用。
	AuthActive = "active"
	// AuthRevoked 表示授权已被授权人撤销。
	AuthRevoked = "revoked"
	// AuthExpired 表示授权已过到期时间且尚未使用。
	AuthExpired = "expired"
	// AuthUsed 表示授权已用于一次成功代转。
	AuthUsed = "used"
)

// CreateAuthorizationRequest 是创建限时一次性代转授权的业务参数
// （幂等判定以此为准）。
type CreateAuthorizationRequest struct {
	Operator      string    // 操作者，必须是当前持有人（授权人）且可用
	Reason        string    // 原因
	RequestID     string    // 请求号，与发行、转让共用同一操作者的请求号范围
	AuthID        string    // 唯一授权编号
	ItemID        string    // 已发行藏品编号
	TrusteeID     string    // 受托账户，可凭授权发起代转
	ToID          string    // 固定接收账户，代转只能转入该账户
	ExpectedOwner string    // 期望当前持有人
	ExpectedVer   int64     // 期望当前持有版本；授权绑定该持有版本
	ExpiresAt     time.Time // 绝对到期时间，必须晚于当前时间
	// Price 是代转成交价款（分），在创建授权时确定，执行代转时不得改价；
	// 非负，未填按 0。
	Price int64
}

// RevokeAuthorizationRequest 是撤销授权的业务参数。
type RevokeAuthorizationRequest struct {
	Operator  string // 操作者，必须是授权人
	Reason    string // 原因
	RequestID string // 请求号
	AuthID    string // 待撤销的授权编号
}

// ProxyTransferRequest 是受托人凭授权发起代转的业务参数。
type ProxyTransferRequest struct {
	Operator  string // 操作者，必须是授权的受托人
	Reason    string // 原因
	RequestID string // 请求号
	AuthID    string // 使用的授权编号
}

// Authorization 是一份代转授权的当前内容与状态。
type Authorization struct {
	ID        string    // 授权编号
	ItemID    string    // 绑定的藏品
	GranterID string    // 授权人（创建时的持有人）
	TrusteeID string    // 受托账户
	ToID      string    // 固定接收账户
	ExpiresAt time.Time // 绝对到期时间
	GrantVer  int64     // 创建时绑定的持有版本
	// Price 是创建时确定的代转成交价款（分）；旧登记册中的授权按 0。
	Price     int64
	Status    string    // 当前状态：AuthActive/AuthRevoked/AuthExpired/AuthUsed
	UsedTxSeq int64     // 成功代转的历史序号；未使用为 0
	UsedAt    time.Time // 成功代转时间；未使用为零值
	CreatedAt time.Time // 创建时间
	RevokedAt time.Time // 撤销时间；未撤销为零值
}

// AuthorizationEvent 是授权变更记录中的一条。
type AuthorizationEvent struct {
	Seq        int64     // 授权变更记录内严格递增的序号
	AuthID     string    // 授权编号
	ItemID     string    // 藏品编号
	Kind       string    // "create" / "revoke" / "use"
	Operator   string    // 操作者账户编号（use 时为受托人）
	Reason     string    // 操作原因
	RequestID  string    // 请求号
	FromStatus string    // 变更前状态（create 前为空）
	ToStatus   string    // 变更后状态
	TxSeq      int64     // use 时关联的藏品转让历史序号，否则为 0
	OccurredAt time.Time // 发生时间
}

// CreateAuthorizationResult 是创建授权的结果。
type CreateAuthorizationResult struct {
	AuthID   string
	Status   string
	GrantVer int64
	Replayed bool
	Err      error
}

// RevokeAuthorizationResult 是撤销授权的结果。Replayed 为 true 表示该
// (操作者, 请求号) 曾成功或处于状态类业务拒绝；已撤销后再次撤销也回放
// 首次结果。
type RevokeAuthorizationResult struct {
	AuthID   string
	Status   string
	Replayed bool
	Err      error
}

// ProxyTransferResult 是代转的结果，字段语义与 TransferResult 一致。
type ProxyTransferResult struct {
	AuthID   string // 使用的授权编号
	ItemID   string // 藏品编号
	FromID   string // 转让前持有人
	ToID     string // 转让后持有人
	Version  int64  // 转让后版本
	TxSeq    int64  // 转让历史序号
	Replayed bool   // 是否为重复提交回放的首次结果
	Err      error  // 业务拒绝；成功时为 nil
	// Price 是授权创建时确定的成交价款（分）；Payables 是各版税收款账户
	// 的应付明细（含零金额）；Remainder 是归转让前持有人的剩余收入。
	Price     int64
	Payables  []RoyaltyPayable
	Remainder int64
}

// ---- 版税规则与应付记录 ----

// RoyaltyRateBase 是版税比例的分母：比例以万分之一为单位。
const RoyaltyRateBase = 10000

// RoyaltyShare 是版税规则中一个收款账户的份额。
type RoyaltyShare struct {
	AccountID string // 收款账户，规则内只能出现一次
	Rate      int64  // 比例，万分之一，取值 1..10000；全部份额合计不超过 10000
}

// SetRoyaltyRequest 是设置或清空系列版税规则的业务参数（幂等判定以此
// 为准）。Shares 为空表示清空规则，即不收版税。
type SetRoyaltyRequest struct {
	Operator  string         // 操作者，必须是系列创建账户且可用
	Reason    string         // 原因
	RequestID string         // 请求号，与发行、转让等共用同一操作者的请求号范围
	SeriesID  string         // 系列编号
	Shares    []RoyaltyShare // 新规则；空表示不收版税
}

// SetRoyaltyResult 是设置版税规则的结果。
type SetRoyaltyResult struct {
	SeriesID string         // 系列编号
	Shares   []RoyaltyShare // 本次生效的规则（按收款账户排序规范化后）
	Replayed bool           // 是否为重复提交回放的首次结果
	Err      error          // 业务拒绝；成功时为 nil
}

// RoyaltyEvent 是一次版税规则变更记录，包含操作者、原因、请求号与前后
// 内容；按发生先后排列。
type RoyaltyEvent struct {
	Seq        int64          // 规则变更记录内严格递增的序号
	SeriesID   string         // 系列编号
	Operator   string         // 操作者账户编号
	Reason     string         // 操作原因
	RequestID  string         // 请求号
	Before     []RoyaltyShare // 变更前规则（首次设置前为空）
	After      []RoyaltyShare // 变更后规则
	OccurredAt time.Time      // 发生时间
}

// RoyaltyPayable 是一笔转让中某个版税收款账户的应付明细。
type RoyaltyPayable struct {
	AccountID string // 收款账户
	Rate      int64  // 计算所用比例（万分之一）
	Amount    int64  // 应付金额（分）：价款乘比例除以 10000 向下取整，零金额也保留
}

// TransferRoyalty 是一笔成功转让的版税计算依据与全部金额。
type TransferRoyalty struct {
	TxSeq     int64            // 转让历史序号
	ItemID    string           // 藏品编号
	Price     int64            // 成交价款（分）
	Payables  []RoyaltyPayable // 各收款账户应付明细（含零金额；无规则时为空）
	Remainder int64            // 扣除应付后的剩余收入，归转让前持有人
	OwnerID   string           // 转让前持有人，即剩余收入的归属账户
}

// PayableEntry 是按收款账户查询时的一条应付明细。
type PayableEntry struct {
	TxSeq  int64  // 转让历史序号
	ItemID string // 藏品编号
	Price  int64  // 该笔成交价款（分）
	Rate   int64  // 计算所用比例（万分之一）
	Amount int64  // 应付金额（分）
}

// ---- 藏品拆分意向 ----

// 拆分意向生命周期状态。已失效与已过期不单独落盘，按当前状态与时间实时
// 判断；已拒绝与已撤回是落盘的终态。
const (
	// SplitPending 表示意向已创建，尚有参与账户未答复。
	SplitPending = "pending"
	// SplitAgreed 表示全部参与账户已同意各自份额。
	SplitAgreed = "agreed"
	// SplitRejected 表示任一参与账户拒绝了自己的份额。
	SplitRejected = "rejected"
	// SplitWithdrawn 表示发起人已撤回意向。
	SplitWithdrawn = "withdrawn"
	// SplitInvalid 表示意向已失效：藏品持有版本已变化，或发起人、任一
	// 参与账户已停用；藏品转回原持有人也不能恢复。
	SplitInvalid = "invalid"
	// SplitExpired 表示意向未失效但已过绝对到期时间。
	SplitExpired = "expired"
)

// 参与账户的答复。
const (
	// SplitAnswerAgree 表示同意自己的份额。
	SplitAnswerAgree = "agree"
	// SplitAnswerReject 表示拒绝自己的份额。
	SplitAnswerReject = "reject"
)

// SplitShare 是拆分意向中一个参与账户的份额。份额以万分之一为单位，
// 每份 1..10000，全部份额合计必须为 10000。
type SplitShare struct {
	AccountID string // 参与账户，方案内不能重复
	Share     int64  // 份额，万分之一，取值 1..10000
}

// CreateSplitIntentRequest 是创建拆分意向的业务参数（幂等判定以此为准；
// 份额名单仅排列不同视为相同内容）。
type CreateSplitIntentRequest struct {
	Operator      string       // 操作者，必须是当前持有人（发起人）且可用
	Reason        string       // 原因
	RequestID     string       // 请求号，与发行、转让等共用同一操作者的请求号范围
	IntentID      string       // 唯一意向编号
	ItemID        string       // 已发行藏品编号
	ExpectedOwner string       // 期望当前持有人
	ExpectedVer   int64        // 期望当前持有版本；意向绑定该持有版本
	ExpiresAt     time.Time    // 绝对到期时间，必须晚于当前时间
	Shares        []SplitShare // 分配方案，至少两个账户；发起人可列入，其份额视为已同意
}

// AnswerSplitIntentRequest 是参与账户答复自己份额的业务参数。
type AnswerSplitIntentRequest struct {
	Operator  string // 操作者，必须是方案中的参与账户
	Reason    string // 原因
	RequestID string // 请求号
	IntentID  string // 意向编号
	Agree     bool   // true 同意，false 拒绝
}

// WithdrawSplitIntentRequest 是发起人撤回拆分意向的业务参数。
type WithdrawSplitIntentRequest struct {
	Operator  string // 操作者，必须是发起人
	Reason    string // 原因
	RequestID string // 请求号
	IntentID  string // 意向编号
}

// SplitParty 是拆分意向中一个参与账户的份额与当前答复。
type SplitParty struct {
	AccountID string // 参与账户
	Share     int64  // 份额，万分之一
	// Answer 是该账户的当前答复：SplitAnswerAgree/SplitAnswerReject；
	// 空表示尚未答复。发起人列入方案时创建即为 SplitAnswerAgree。
	Answer string
}

// SplitIntent 是一份拆分意向的当前内容与状态。意向只记录未来拆分的
// 约定，不改变藏品编号、持有人、持有版本与版税应付。
type SplitIntent struct {
	ID          string       // 意向编号
	ItemID      string       // 藏品编号
	InitiatorID string       // 发起人（创建时的持有人）
	Shares      []SplitParty // 分配方案与各方答复（按账户排序）
	GrantVer    int64        // 创建时绑定的持有版本
	ExpiresAt   time.Time    // 绝对到期时间
	Status      string       // 当前状态：SplitPending/SplitAgreed/SplitRejected/SplitWithdrawn/SplitInvalid/SplitExpired
	CreatedAt   time.Time    // 创建时间
	EndedAt     time.Time    // 拒绝或撤回时间；未终结为零值
}

// SplitIntentEvent 是拆分意向变更记录中的一条：创建、首次答复与撤回
// 各记录一条，按发生先后排列。重复答复与重复撤回不新增记录。
type SplitIntentEvent struct {
	Seq        int64     // 意向变更记录内严格递增的序号
	IntentID   string    // 意向编号
	ItemID     string    // 藏品编号
	Kind       string    // "create" / "answer" / "withdraw"
	Operator   string    // 操作者账户编号
	Reason     string    // 操作原因
	RequestID  string    // 请求号
	Answer     string    // answer 时的答复（agree/reject），否则为空
	FromStatus string    // 变更前状态（create 前为空）
	ToStatus   string    // 变更后状态
	OccurredAt time.Time // 发生时间
}

// CreateSplitIntentResult 是创建拆分意向的结果。
type CreateSplitIntentResult struct {
	IntentID string
	Status   string
	GrantVer int64
	Replayed bool
	Err      error
}

// AnswerSplitIntentResult 是答复拆分意向的结果。Status 是答复生效后的
// 意向状态。
type AnswerSplitIntentResult struct {
	IntentID string
	Status   string
	Replayed bool
	Err      error
}

// WithdrawSplitIntentResult 是撤回拆分意向的结果。
type WithdrawSplitIntentResult struct {
	IntentID string
	Status   string
	Replayed bool
	Err      error
}

