62	func setRoyaltyParamsSig(req SetRoyaltyRequest, shares []royaltyShare) string {
63		b, _ := json.Marshal(struct {
64			Kind     string         `json:"kind"`
65			SeriesID string         `json:"series_id"`
66			Shares   []royaltyShare `json:"shares"`
67			Reason   string         `json:"reason"`
68		}{"royalty_set", req.SeriesID, shares, req.Reason})
69		return string(b)
70	}
