8	// 验证含零字符的账户编号与请求号不再互相占用请求号。
9	func TestNULRequestKeyIsolation(t *testing.T) {
10		dir := t.TempDir()
11		r, err := Create(dir)
12		if err != nil {
13			t.Fatal(err)
14		}
15		// 账户甲 "a"，账户乙 "a\x00b"
16		for _, id := range []string{"a", "a\x00b"} {
17			if err := r.RegisterAccount(id, ""); err != nil {
18				t.Fatal(err)
19			}
20		}
21		if err := r.CreateSeries("s1", "a", ""); err != nil {
22			t.Fatal(err)
23		}
24		if err := r.CreateSeries("s2", "a\x00b", ""); err != nil {
25			t.Fatal(err)
26		}
27	
28		// 甲用请求号 "b\x00c" 发行 item1
29		res1, err := r.Issue(IssueRequest{Operator: "a", Reason: "r", RequestID: "b\x00c",
30			ItemID: "item1", SeriesID: "s1", BatchNo: "B", HolderID: "a"})
31		if err != nil {
32			t.Fatalf("甲发行失败: %v", err)
33		}
34		// 乙用请求号 "c" 发行 item2 —— 旧代码会在此误报请求号冲突
35		res2, err := r.Issue(IssueRequest{Operator: "a\x00b", Reason: "r", RequestID: "c",
36			ItemID: "item2", SeriesID: "s2", BatchNo: "B", HolderID: "a\x00b"})
37		if err != nil {
38			t.Fatalf("乙发行被错误拒绝: %v", err)
39		}
40		if res1.TxSeq == res2.TxSeq || res2.ItemID != "item2" {
41			t.Fatalf("结果混淆: %+v %+v", res1, res2)
42		}
43	
44		// 甲用相同请求号与内容重提 → 回放自己的首次结果
45		again, err := r.Issue(IssueRequest{Operator: "a", Reason: "r", RequestID: "b\x00c",
46			ItemID: "item1", SeriesID: "s1", BatchNo: "B", HolderID: "a"})
