package registry

import (
	"errors"
	"reflect"
	"testing"
)

// failSaveStore 包裹真实 store，只让指定的一次保存调用失败；其余调用
// （包括失败后的重试与登记册重开）全部透传到底层原子落盘，因此失败期间
// 磁盘上的原登记册始终可以正常读取。
type failSaveStore struct {
	inner *store
	// remaining 是还需要强制失败的保存次数；为 0 后恢复正常保存。
	remaining int
	failedAt  []string
}

func (s *failSaveStore) save(snap *snapshot) error {
	if s.remaining > 0 {
		s.remaining--
		s.failedAt = append(s.failedAt, snap.Requests[""].RequestID)
		return errors.New("registry: 测试注入的保存失败")
	}
	return s.inner.save(snap)
}

// 整批转让在内容替换已保存数据之前写入失败（原登记册仍可正常读取）时，
// 请求必须整体失败并返回保存错误，磁盘上的原登记册不留下任何部分转让；
// 恢复后用完全相同的请求号、原因与条目再次提交，应完整执行一次而不是
// 回放或请求号冲突。本用例在已有成功转让与应付记录的登记册上验证，并
// 同时确认清单外藏品不被失败影响。
func TestTransferBatchSaveFailureRollbackAndRetry(t *testing.T) {
	dir := tempDir(t)
	r := mustCreate(t, dir)
	setupBatchTransferWorld(t, r)

	// 先制造一笔已落盘的成功转让（i1 bob@1 -> carol@2）及其应付记录，
	// 作为失败前最后一条历史：序号 6，carol 1000、dave 500。
	prev, err := r.Transfer(TransferRequest{
		Operator: "bob", Reason: "先前成交", RequestID: "rp-old", ItemID: "i1",
		ExpectedOwner: "bob", ExpectedVer: 1, ToID: "carol", Price: 10000,
	})
	if err != nil {
		t.Fatalf("seed transfer: %v", err)
	}
	if prev.TxSeq != 6 {
		t.Fatalf("seed TxSeq = %d, want 6", prev.TxSeq)
	}
	// 让 i1 回到 bob 手中、版本 3，以便整批请求以持有人 bob、版本 3 提交；
	// 这笔转让序号 7，是整批前真正的最后一条转让历史。
	back, err := r.Transfer(TransferRequest{
		Operator: "carol", Reason: "退回", RequestID: "rp-back", ItemID: "i1",
		ExpectedOwner: "carol", ExpectedVer: 2, ToID: "bob", Price: 5000,
	})
	if err != nil {
		t.Fatalf("return transfer: %v", err)
	}
	if back.TxSeq != 7 {
		t.Fatalf("return TxSeq = %d, want 7", back.TxSeq)
	}

	// 失败前各收款账户的既有应付明细（内容、顺序、金额稍后逐项比对）。
	snapshotPayables := func() map[string][]PayableEntry {
		out := map[string][]PayableEntry{}
		for _, acc := range []string{"carol", "dave", "alice"} {
			ps, err := r.PayablesOf(acc)
			if err != nil {
				t.Fatalf("PayablesOf %s: %v", acc, err)
			}
			out[acc] = append([]PayableEntry(nil), ps...)
		}
		return out
	}
	payBefore := snapshotPayables()
	if len(payBefore["carol"]) != 2 || len(payBefore["dave"]) != 1 {
		t.Fatalf("seed payables = carol %+v dave %+v", payBefore["carol"], payBefore["dave"])
	}
	// 清单外藏品 i5（属于 carol，版本 1）与 i4 之外再用 i5 做不受影响的对照。
	i5Before, err := r.GetHolding("i5")
	if err != nil {
		t.Fatal(err)
	}
	i5HistBefore, err := r.History("i5")
	if err != nil {
		t.Fatal(err)
	}

	// 整批至少两件、接收账户不同，且含版税规则藏品：
	// i1（s1，carol10%+dave5%，bob@3 -> alice）、i2（s2，carol100%，bob@1 -> dave）、
	// i4（s3 无版税，bob@1 -> carol）。
	req := TransferBatchRequest{
		Operator: "bob", Reason: "整批转出", RequestID: "rb-fail",
		Entries: []TransferBatchEntry{
			{ItemID: "i1", ToID: "alice", ExpectedOwner: "bob", ExpectedVer: 3, Price: 10000},
			{ItemID: "i2", ToID: "dave", ExpectedOwner: "bob", ExpectedVer: 1, Price: 333},
			{ItemID: "i4", ToID: "carol", ExpectedOwner: "bob", ExpectedVer: 1, Price: 500},
		},
	}

	// 注入下一次保存失败：TransferBatch 的业务检查全部通过，仅最终
	// 一次落盘失败。
	fault := &failSaveStore{inner: r.store, remaining: 1}
	r.store = fault

	res, err := r.TransferBatch(req)

	// 保存已恢复：无论失败路径如何，后续提交都能真正落盘。
	r.store = fault.inner
	if fault.remaining != 0 {
		t.Fatalf("fault not exercised, remaining = %d", fault.remaining)
	}
	if err == nil {
		t.Fatalf("保存失败必须返回错误，得到结果 %+v", res)
	}
	if errors.Is(err, ErrConflict) || errors.Is(err, ErrAccountInactive) ||
		errors.Is(err, ErrSameAccount) || errors.Is(err, ErrRequestConflict) ||
		errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrNotFound) {
		t.Fatalf("应返回保存错误而非业务拒绝，got %v", err)
	}
	if len(res.Items) != 0 || res.ItemID != "" || res.Replayed {
		t.Fatalf("失败不能返回任何一件已转让成功的结果: %+v", res)
	}

	// 调用者继续使用同一个已打开的登记册查询：每件仍属于原持有人、
	// 版本没有增加，历史中没有这次请求。
	wantHolding := map[string]struct {
		owner string
		ver   int64
	}{
		"i1": {"bob", 3},
		"i2": {"bob", 1},
		"i4": {"bob", 1},
	}
	for item, want := range wantHolding {
		h, err := r.GetHolding(item)
		if err != nil {
			t.Fatalf("GetHolding %s: %v", item, err)
		}
		if h.OwnerID != want.owner || h.Version != want.ver {
			t.Errorf("失败后持有变化 %s = %+v, want %+v", item, h, want)
		}
		hist, err := r.History(item)
		if err != nil {
			t.Fatalf("History %s: %v", item, err)
		}
		for _, e := range hist {
			if e.RequestID == "rb-fail" {
				t.Fatalf("%s 历史出现失败请求: %+v", item, e)
			}
		}
	}
	// i1 失败前已有 3 条历史（发行 + 两笔单件转让），i2/i4 只有发行。
	if hist, _ := r.History("i1"); len(hist) != 3 {
		t.Fatalf("i1 history = %+v, want 3 entries", hist)
	}
	for _, item := range []string{"i2", "i4"} {
		if hist, _ := r.History(item); len(hist) != 1 {
			t.Fatalf("%s history = %+v, want only issue entry", item, hist)
		}
	}

	// 失败不消耗转让历史序号：下一条仍是 8。
	if r.state.NextSeq != 8 {
		t.Fatalf("NextSeq = %d, want 8（失败不消耗序号）", r.state.NextSeq)
	}
	if _, ok := r.state.Royalties[8]; ok {
		t.Fatal("失败的整批不能留下序号 8 的应付记录")
	}

	// 既有成功转让与应付记录完整保留：内容、顺序、金额都不变。
	for _, acc := range []string{"carol", "dave", "alice"} {
		ps, err := r.PayablesOf(acc)
		if err != nil {
